mapper.select:
select t1.* from (SELECT cc.contract_id, cf.cashflow_id, cc.tenant_id bp_id, (select bm.bp_name from hls_bp_master bm where bm.bp_id = cc.tenant_id) bp_name, cc.contract_number, cf.cf_item, (select hci.description from hls_cashflow_item hci where hci.cf_item = cf.cf_item) cashflow_item_desc, cf.due_amount, cf.times, nvl(cf.received_amount, 0) as received_amount, cf.due_amount - nvl(cf.received_amount, 0) as outstanding_amount, cf.due_date, nvl(cf.last_received_date, (select max(cw.write_off_date) from csh_write_off cw where cw.cashflow_id = cf.cashflow_id and cw.reversed_flag = 'N')) as last_received_date, (select fc.currency_name from fnd_currency fc where fc.currency_code = cc.currency) currency_name, (select fu.unit_name from fnd_org_unit fu where fu.unit_id = cc.unit_id) business_unit, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'RPT.DATA_SOURCES_FLAG' and sv.code_value = nvl('CONTRACT', (select rt.sources_flag from rpt_rental_income_rate rt where rt.cashflow_id = cf.cashflow_id))) sources_flag_n FROM con_contract cc, con_contract_cashflow cf where cf.contract_id = cc.contract_id and cf.cf_direction = 'INFLOW' union all SELECT t.cashflow_id, t.contract_id, t.bp_id, t.bp_name, t.contract_number, t.cf_item, (select hci.description from hls_cashflow_item hci where hci.cf_item = t.cf_item) cashflow_item_desc, t.due_amount, t.times, t.received_amount, t.due_amount - nvl(t.received_amount, 0) as outstanding_amount, t.due_date, t.last_received_date, t.currency_name, t.business_unit, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'RPT.DATA_SOURCES_FLAG' and sv.code_value = t.sources_flag) sources_flag_n FROM rpt_rental_income_rate t where t.sources_flag = 'IMPORT') t1 1=1
and t1.due_date <= #{dueDateTo}
and t1.due_date >= #{dueDateFrom}
AND t1.bp_name LIKE concat(concat('%',#{bpName}),'%')
AND t1.currency_name LIKE concat(concat('%',#{currencyName}),'%')
AND t1.contract_number LIKE concat(concat('%',#{contractNumber}),'%')
and t1.due_amount >= #{dueAmountFrom}
and t1.due_amount <= #{dueAmountTo}
AND t1.business_unit LIKE concat(concat('%',#{businessUnit}),'%')
and t1.times = #{times}
and t1.outstanding_amount >= #{outstandingAmountFrom}
and t1.outstanding_amount <= #{outstandingAmountTo}
AND t1.cashflow_item_desc LIKE concat(concat('%',#{cashflowItemDesc}),'%')
AND t1.cf_item = #{cfItem}
order by t1.contract_id desc

SELECT t1.record_id, t1.cashflow_id, t1.contract_id, t1.bp_id, t1.bp_name, t1.cf_item, (select hci.description from hls_cashflow_item hci where hci.cf_item = t1.cf_item) cashflow_item_desc, t1.organization_name, t1.contract_number, t1.due_date, t1.last_received_date, t1.currency_name, t1.int_rate, t1.due_amount, t1.received_amount, t1.overdue_amount, t1.due_amount - nvl(t1.received_amount, 0) as outstanding_amount, t1.business_unit, t1.plan_judge, t1.sources_flag, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'RPT.DATA_SOURCES_FLAG' and sv.code_value = t1.sources_flag) sources_flag_n, t1.times FROM rpt_rental_income_rate t1 1=1
and t1.due_date <= #{dueDateTo}
and t1.due_date >= #{dueDateFrom}
AND t1.bp_name LIKE concat(concat('%',#{bpName}),'%')
AND t1.currency_name LIKE concat(concat('%',#{currencyName}),'%')
AND t1.contract_number LIKE concat(concat('%',#{contractNumber}),'%')
and t1.due_amount >= #{dueAmountFrom}
and t1.due_amount <= #{dueAmountFrom}
AND t1.business_unit LIKE concat(concat('%',#{businessUnit}),'%')
and t1.times <= #{times}
and t1.outstanding_amount >= #{outstandingAmountFrom}
and t1.outstanding_amount <= #{outstandingAmountTo}
AND t1.cashflow_item_desc LIKE concat(concat('%',#{cashflowItemDesc}),'%')
order by t1.contract_id desc

SELECT t1.* FROM (select nvl((SELECT SUM(cf.due_amount) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id), 0) + nvl((SELECT SUM(rt.due_amount) FROM rpt_rental_income_rate rt WHERE rt.business_unit = fu.unit_name AND rt.sources_flag = 'IMPORT'), 0) due_amount, nvl((SELECT SUM(cf.received_amount) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id), 0) + nvl((SELECT SUM(rt.received_amount) FROM rpt_rental_income_rate rt WHERE rt.business_unit = fu.unit_name AND rt.sources_flag = 'IMPORT'), 0) received_amount, (SELECT MIN(cc.int_rate) FROM con_contract cc WHERE fu.unit_id = cc.unit_id) int_rate, (SELECT MIN(cf.due_date) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id) due_date, fu.unit_name business_unit, (SELECT fc.currency_name FROM fnd_currency fc, con_contract cc WHERE fc.currency_code = cc.currency and fu.unit_id = cc.unit_id and rownum=1) currency_name, nvl((SELECT nvl(SUM(cf.due_amount), 0) - nvl(SUM(cf.received_amount), 0) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id), 0) + nvl((SELECT nvl(SUM(rt.due_amount), 0) - nvl(SUM(rt.received_amount), 0) FROM rpt_rental_income_rate rt WHERE rt.business_unit = fu.unit_name AND rt.sources_flag = 'IMPORT'), 0) AS overdue_amount,
round((nvl((SELECT SUM(cf.received_amount) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id), 0) + nvl((SELECT SUM(rt.received_amount) FROM rpt_rental_income_rate rt WHERE rt.business_unit = fu.unit_name AND rt.sources_flag = 'IMPORT'), 0)) / (nvl((SELECT SUM(cf.due_amount) FROM con_contract cc, con_contract_cashflow cf WHERE cc.contract_id = cf.contract_id and fu.unit_id = cc.unit_id), 0) + nvl((SELECT SUM(rt.due_amount) FROM rpt_rental_income_rate rt WHERE rt.business_unit = fu.unit_name AND rt.sources_flag = 'IMPORT'), 0)), 4) received_rate from fnd_org_unit fu where exists (select 1 from con_contract cc where cc.unit_id = fu.unit_id) or exists (select 1 from rpt_rental_income_rate rt where rt.business_unit = fu.unit_name)) t1 1=1
and t1.due_date >= #{dueDateFrom}
and t1.due_date <= #{dueDateTo}
AND t1.currency_name LIKE concat(concat('%',#{currencyName}),'%')
